"""The package-route token table and the closed recipe templates built from it (layer L2-pure: data only, imports
nothing from scripts).

Every token a package route may emit is an allowed row, and every token the reviewed design refuses is a forbidden
row; each row cites the manager's official documentation page. package_routes renders only allowed tokens, so a
token absent from the table is refused as well. The recipes are the only argv shapes: read-only recipes for the
read-only runner, run recipes rendered for the coordinator after the ticket.
"""
from collections import namedtuple
import re
from types import MappingProxyType

# A row: the token, whether PatchCairn may emit it, its official documentation page and its manager.
Token = namedtuple("Token", "token allowed url manager")

# Some allowed tokens have a second documented meaning; package_routes' fixed grammar places each one only where the
# allowed meaning applies: winget's --name only after "source export", apt's -o only directly before one of the two
# conffile constants, and -s only as apt-get's simulation (sudo's -s is never emitted: sudo is always followed by an
# absolute path). These tokens are therefore allowed rows and not forbidden ones.
